(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.017-t*0.28)*18 + Math.sin(x*0.014+t*0.33)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.022-t*0.4)*10 + Math.cos(my*0.019+t*0.35)*7;
  const w2y = Math.cos(my*0.021+t*0.38)*10 + Math.sin(mx*0.02-t*0.42)*7;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+1)*60, 220+Math.sin(t*0.75+4)*40, 0.085, 1.8]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS2 += Math.sin(d*f*1.6 - t*sp*1.3 + 0.8)*0.5;
    iS2 += Math.sin(d*f*1.2 + t*sp*0.9 + 2.1)*0.5;
  }
  const n = src.length;
  const act = aS/n + aS2/n, inh = iS/n + iS2/n;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = (Math.sin(sx*0.08+sy*0.06-t*1.5) + Math.sin(sx*0.07-sy*0.09+t*1.8))*0.3;
  const bg3 = Math.sin(sx*0.16+sy*0.12+t*2.5)*0.15 + Math.sin((sx-sy)*0.1-t*2)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const spiral1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = (Math.sin(dist*0.07+ang*2-t*0.9) + Math.sin(dist*0.06-ang*5+t*1.6))*0.25;
  const spiral = spiral1 + spiral2;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((act*0.6 - inh*0.9 + bg*0.5 - spiral*0.3)*1.8);
  const reaction = Math.tanh((rd1 + rd2*0.4)*1.5);
  const cell1 = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2 = Math.tanh((Math.cos(sx*0.12-t)*Math.sin(sy*0.18+t*0.7))*1.2)*0.15;
  const cell = cell1 + cell2;
  const fine = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.05;
  const blend = reaction*0.65 + cell*0.2 + fine;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,42,88],[18,85,120],[25,138,128],[85,170,110],
    [180,185,75],[215,165,60],[210,115,65],[185,70,70],
    [120,40,65],[65,22,55],[30,15,48],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const breath = 0.92+Math.sin(t*0.4)*0.04+Math.sin(t*0.7+1)*0.04;
  const lum = (0.85+Math.sin(reaction*Math.PI)*0.15)*breath;
  const edge = Math.abs(reaction)>0.65 ? 1.0+(Math.abs(reaction)-0.65)*0.5 : 1.0;
  const glow = Math.max(0, reaction-0.5)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*255)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*180)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*120)|0)
  ];
}
